<?php
namespace App\Http\Controllers;use App\Models\SupportMessage;use App\Models\SupportTicket;use Illuminate\Http\Request;
class SupportController extends Controller{public function index(Request $r){$q=SupportTicket::with(['user:id,name,email','messages.user:id,name,role'])->latest();if($r->user()->role!=='admin')$q->where('user_id',$r->user()->id);return view('support.index',['tickets'=>$q->paginate(20),'isAdmin'=>$r->user()->role==='admin']);}public function store(Request $r){$d=$r->validate(['category'=>'required|in:trip,payment,driver_account,safety,technical,privacy,other','subject'=>'required|string|min:5|max:150','message'=>'required|string|min:10|max:5000']);$ticket=SupportTicket::create(['user_id'=>$r->user()->id,'category'=>$d['category'],'subject'=>$d['subject'],'priority'=>$d['category']==='safety'?'urgent':'normal']);SupportMessage::create(['ticket_id'=>$ticket->id,'user_id'=>$r->user()->id,'message'=>$d['message']]);return back()->with('success','Caso de soporte creado.');}public function reply(Request $r,SupportTicket $ticket){abort_unless($r->user()->role==='admin'||$ticket->user_id===$r->user()->id,403);abort_if($ticket->status==='closed',422,'El caso esta cerrado.');$d=$r->validate(['message'=>'required|string|min:2|max:5000']);SupportMessage::create(['ticket_id'=>$ticket->id,'user_id'=>$r->user()->id,'message'=>$d['message']]);$ticket->update(['status'=>$r->user()->role==='admin'?'waiting_user':'in_progress','assigned_to'=>$r->user()->role==='admin'?$r->user()->id:$ticket->assigned_to]);return back()->with('success','Respuesta enviada.');}public function update(Request $r,SupportTicket $ticket){$d=$r->validate(['status'=>'required|in:open,in_progress,waiting_user,resolved,closed','priority'=>'required|in:low,normal,high,urgent']);$ticket->update(['status'=>$d['status'],'priority'=>$d['priority'],'assigned_to'=>$r->user()->id,'resolved_at'=>in_array($d['status'],['resolved','closed'])?now():null]);return back()->with('success','Caso actualizado.');}}